import os, glob
from datetime import datetime, timedelta

REPO = '/mnt/c/Projects/biotech_screener/biotech-screener'
agents_dir = os.path.join(REPO, 'agents')
now = datetime.now()
fresh_threshold = timedelta(minutes=30)
stale_threshold = timedelta(hours=24)

fresh, stale, very_stale = [], [], []
for agent_dir in sorted(os.listdir(agents_dir)):
    if agent_dir.startswith('hermes-') or agent_dir.startswith('AGENT'):
        continue
    for subdir in ['output', 'memory']:
        d = os.path.join(agents_dir, agent_dir, subdir)
        if os.path.exists(d):
            files = glob.glob(os.path.join(d, '*'))
            if files:
                latest = max(files, key=os.path.getmtime)
                age = now - datetime.fromtimestamp(os.path.getmtime(latest))
                if age < fresh_threshold:
                    fresh.append((agent_dir, int(age.total_seconds()/60), 'min'))
                elif age < stale_threshold:
                    stale.append((agent_dir, int(age.total_seconds()/3600), 'h'))
                else:
                    very_stale.append((agent_dir, int(age.total_seconds()/3600), 'h'))
                break

print(f"✓ FRESH ({len(fresh)} agents):")
for n, age, u in fresh: print(f"  {n:<32} ({age}{u} ago)")
print(f"\n~ OK <24h ({len(stale)} agents):")
for n, age, u in stale: print(f"  {n:<32} ({age}{u} ago)")
print(f"\n⚠️  STILL STALE ({len(very_stale)} agents):")
for n, age, u in very_stale: print(f"  {n:<32} ({age}{u} ago)")
EOF

